        "field_path": [
          "review_planning_B",
          "scope_interpretation_cautions"
        ],
        "value": "Mechanistic claims are largely based on preclinical models or correlational clinical data; distinguish between observed association and proven mechanism.",
        "role": "evidence",
        "snapshot_ids": [
          "snapshot::05df8fdca8777120f8d54673",
          "snapshot::78c448ac93100acb4520a4dd"
        ]
